"""Core of the Tendora dream apparatus: the journal and the acts upon it.

Design rules (these are also recorded as chisels and boundaries in the journal
of the world that ships this code):

* The journal is append-only.  Nothing here rewrites or deletes a line.
* Every entry carries the hash of the previous entry, so accidental edits and
  truncations are detected.  This is a trail, not a lock: anyone with write
  access could re-chain the file.  Treat it as evidence, not proof.
* Rehearsals run in a disposable copy of the world.  They never touch the
  world itself.
* The apparatus never reaches outside the world directory except to create
  the disposable copy under the system temporary directory.
"""

from __future__ import annotations

import hashlib
import json
import os
import shutil
import subprocess
import tempfile
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple

KINDS = ("probe", "chisel", "beam", "boundary", "rehearsal", "receipt", "cognition")
RESOLVABLE = ("probe",)
RETIRABLE = ("chisel", "beam", "boundary")
GENESIS = "0" * 64
JOURNAL = Path("ledger") / "journal.jsonl"
MARKER = "CONTINUING.md"
IGNORED_IN_COPIES = (".git", "__pycache__", "*.pyc", ".claude")
OUTPUT_TAIL = 2000


class LedgerError(Exception):
    """Raised when the journal is unreadable, broken, or an act is invalid."""


# ---------------------------------------------------------------------------
# small pure helpers


def canonical(obj) -> str:
    """Deterministic JSON used for hashing and for storage."""
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def digest(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def default_actor() -> str:
    return os.environ.get("TENDORA_ACTOR") or os.environ.get("USER") or "unknown"


def tail(text: str, limit: int = OUTPUT_TAIL) -> str:
    text = text or ""
    return text if len(text) <= limit else "..." + text[-limit:]


def find_world(start: Optional[os.PathLike] = None) -> Path:
    """Walk upward from ``start`` (default: cwd) until a world root is found."""
    here = Path(start or os.getcwd()).resolve()
    for candidate in (here, *here.parents):
        if (candidate / JOURNAL).exists() or (candidate / MARKER).exists():
            return candidate
    raise LedgerError(
        "not inside a Tendora world: no %s or %s found at or above %s"
        % (JOURNAL, MARKER, here)
    )


def snapshot(root: Path) -> Dict[str, str]:
    """Map of relative path -> content hash for every regular file under root."""
    out: Dict[str, str] = {}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in (".git", "__pycache__")]
        for name in filenames:
            path = Path(dirpath) / name
            try:
                data = path.read_bytes()
            except OSError:
                continue
            out[str(path.relative_to(root))] = hashlib.sha256(data).hexdigest()
    return out


def git_state(root: Path) -> str:
    """'none' if not a repository, 'clean' or 'dirty' otherwise."""
    try:
        proc = subprocess.run(
            ["git", "status", "--porcelain"],
            cwd=root,
            capture_output=True,
            text=True,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired):
        return "none"
    if proc.returncode != 0:
        return "none"
    return "dirty" if proc.stdout.strip() else "clean"


# ---------------------------------------------------------------------------
# the world


class World:
    """A directory with a journal.  All acts go through :meth:`append`."""

    def __init__(self, root: os.PathLike):
        self.root = Path(root).resolve()
        self.journal = self.root / JOURNAL

    # -- reading -----------------------------------------------------------

    def entries(self) -> List[dict]:
        if not self.journal.exists():
            return []
        out: List[dict] = []
        with self.journal.open(encoding="utf-8") as fh:
            for number, line in enumerate(fh, 1):
                line = line.strip()
                if not line:
                    continue
                try:
                    out.append(json.loads(line))
                except json.JSONDecodeError as exc:
                    raise LedgerError("journal line %d is not JSON: %s" % (number, exc))
        return out

    def verify_chain(self, entries: Optional[List[dict]] = None) -> List[str]:
        """Return a list of problems.  Empty list means the chain is intact."""
        entries = self.entries() if entries is None else entries
        problems: List[str] = []
        prev = GENESIS
        for index, entry in enumerate(entries, 1):
            if not isinstance(entry, dict):
                problems.append("entry %d: not an object" % index)
                prev = ""
                continue
            body = {k: v for k, v in entry.items() if k != "hash"}
            if entry.get("seq") != index:
                problems.append("entry %d: seq is %r" % (index, entry.get("seq")))
            if entry.get("prev") != prev:
                problems.append("entry %d: prev does not match the previous hash" % index)
            if entry.get("hash") != digest(canonical(body)):
                problems.append("entry %d: hash does not match content" % index)
            if entry.get("kind") not in KINDS:
                problems.append("entry %d: unknown kind %r" % (index, entry.get("kind")))
            prev = entry.get("hash", "")
        return problems

    def closed(self, entries: Optional[List[dict]] = None) -> Dict[int, int]:
        """Map of closed seq -> seq of the entry that closed it."""
        entries = self.entries() if entries is None else entries
        out: Dict[int, int] = {}
        for entry in entries:
            body = entry.get("body", {})
            for key in ("resolves", "retires"):
                if key in body:
                    out[int(body[key])] = entry["seq"]
        return out

    def active(self, kind: str, entries: Optional[List[dict]] = None) -> List[dict]:
        entries = self.entries() if entries is None else entries
        closed = self.closed(entries)
        return [e for e in entries if e["kind"] == kind and e["seq"] not in closed]

    def get(self, seq: int, entries: Optional[List[dict]] = None) -> dict:
        entries = self.entries() if entries is None else entries
        if 1 <= seq <= len(entries):
            return entries[seq - 1]
        raise LedgerError("no entry %d (journal has %d entries)" % (seq, len(entries)))

    def current_cognition(self, entries: Optional[List[dict]] = None) -> Optional[dict]:
        """The last cognition entry if it is a wake without a later sleep."""
        entries = self.entries() if entries is None else entries
        for entry in reversed(entries):
            if entry["kind"] == "cognition":
                return entry if entry["body"].get("phase") == "wake" else None
        return None

    # -- writing -----------------------------------------------------------

    def append(self, kind: str, body: dict, actor: Optional[str] = None) -> dict:
        if kind not in KINDS:
            raise LedgerError("unknown kind %r; expected one of %s" % (kind, ", ".join(KINDS)))
        entries = self.entries()
        problems = self.verify_chain(entries)
        if problems:
            raise LedgerError(
                "refusing to append to a broken chain:\n  " + "\n  ".join(problems)
            )
        prev = entries[-1]["hash"] if entries else GENESIS
        entry = {
            "seq": len(entries) + 1,
            "ts": now(),
            "kind": kind,
            "actor": actor or default_actor(),
            "body": body,
            "prev": prev,
        }
        entry["hash"] = digest(canonical(entry))
        self.journal.parent.mkdir(parents=True, exist_ok=True)
        with self.journal.open("a", encoding="utf-8") as fh:
            fh.write(canonical(entry) + "\n")
        return entry

    def _require_open(self, seq: int, kinds: Iterable[str], entries: List[dict]) -> dict:
        target = self.get(seq, entries)
        if target["kind"] not in kinds:
            raise LedgerError(
                "entry %d is a %s; expected one of %s" % (seq, target["kind"], ", ".join(kinds))
            )
        closed = self.closed(entries)
        if seq in closed:
            raise LedgerError("entry %d was already closed by entry %d" % (seq, closed[seq]))
        return target

    # -- the acts ----------------------------------------------------------

    def probe(self, question: str, actor: Optional[str] = None) -> dict:
        return self.append("probe", {"question": question}, actor)

    def chisel(self, constraint: str, actor: Optional[str] = None) -> dict:
        return self.append("chisel", {"constraint": constraint}, actor)

    def beam(self, name: str, check: str, actor: Optional[str] = None) -> dict:
        return self.append("beam", {"name": name, "check": check}, actor)

    def boundary(self, refusal: str, actor: Optional[str] = None) -> dict:
        return self.append("boundary", {"refusal": refusal}, actor)

    def receipt(
        self,
        text: str,
        resolves: Optional[int] = None,
        retires: Optional[int] = None,
        actor: Optional[str] = None,
    ) -> dict:
        entries = self.entries()
        body: dict = {"text": text}
        if resolves is not None:
            self._require_open(resolves, RESOLVABLE, entries)
            body["resolves"] = int(resolves)
        if retires is not None:
            self._require_open(retires, RETIRABLE, entries)
            body["retires"] = int(retires)
        return self.append("receipt", body, actor)

    def run_beams(self, timeout: int = 300) -> List[dict]:
        """Run every active beam's check from the world root.  Records nothing."""
        results: List[dict] = []
        for beam in self.active("beam"):
            check = beam["body"]["check"]
            try:
                proc = subprocess.run(
                    check,
                    shell=True,
                    cwd=self.root,
                    capture_output=True,
                    text=True,
                    timeout=timeout,
                )
                code, output = proc.returncode, tail(proc.stdout + proc.stderr)
            except subprocess.TimeoutExpired:
                code, output = -1, "timed out after %ds" % timeout
            results.append(
                {
                    "seq": beam["seq"],
                    "name": beam["body"]["name"],
                    "ok": code == 0,
                    "code": code,
                    "output": output,
                }
            )
        return results

    def rehearse(
        self,
        intent: str,
        command: str,
        timeout: int = 300,
        actor: Optional[str] = None,
    ) -> dict:
        """Run ``command`` in a disposable copy of the world and record what happened."""
        stage = Path(tempfile.mkdtemp(prefix="tendora-rehearsal-"))
        copy = stage / "world"
        try:
            shutil.copytree(
                self.root, copy, ignore=shutil.ignore_patterns(*IGNORED_IN_COPIES)
            )
            before = snapshot(copy)
            try:
                proc = subprocess.run(
                    command,
                    shell=True,
                    cwd=copy,
                    capture_output=True,
                    text=True,
                    timeout=timeout,
                )
                code, output = proc.returncode, tail(proc.stdout + proc.stderr)
            except subprocess.TimeoutExpired:
                code, output = -1, "timed out after %ds" % timeout
            after = snapshot(copy)
            changed = sorted(
                path
                for path in set(before) | set(after)
                if before.get(path) != after.get(path)
            )
        finally:
            shutil.rmtree(stage, ignore_errors=True)
        body = {
            "intent": intent,
            "command": command,
            "exit": code,
            "changed": changed[:200],
            "changed_count": len(changed),
            "output": output,
        }
        return self.append("rehearsal", body, actor)

    def wake(self, actor: Optional[str] = None) -> Tuple[dict, List[dict], Optional[dict]]:
        """Open a cognition.  Verifies the chain, runs the beams, records both."""
        entries = self.entries()
        problems = self.verify_chain(entries)
        if problems:
            raise LedgerError("cannot wake into a broken chain:\n  " + "\n  ".join(problems))
        unslept = self.current_cognition(entries)
        beams = self.run_beams()
        body: dict = {
            "phase": "wake",
            "beams": {str(r["seq"]): r["ok"] for r in beams},
            "git": git_state(self.root),
        }
        if unslept is not None:
            body["unslept"] = unslept["seq"]
        entry = self.append("cognition", body, actor)
        return entry, beams, unslept

    def sleep(self, summary: str, actor: Optional[str] = None) -> Tuple[dict, List[dict]]:
        """Close the current cognition with a summary and a final beam run."""
        beams = self.run_beams()
        body = {
            "phase": "sleep",
            "summary": summary,
            "beams": {str(r["seq"]): r["ok"] for r in beams},
            "git": git_state(self.root),
        }
        entry = self.append("cognition", body, actor)
        return entry, beams


def materialize(root: os.PathLike, actor: Optional[str] = None) -> World:
    """Create an empty world at ``root`` with its first receipt."""
    world = World(root)
    if world.journal.exists() and world.entries():
        raise LedgerError("a world already exists at %s" % world.root)
    world.journal.parent.mkdir(parents=True, exist_ok=True)
    world.journal.touch()
    world.receipt("World materialized at %s." % world.root, actor=actor)
    return world

"""Command-line interface: ``python3 -m tendora <act> ...``.

Every act prints a one-line confirmation with the entry's seq so it can be
referred to later (``receipt --resolves 7``).  ``status`` and ``wake`` print a
briefing meant to be read by whoever inhabits the world next.
"""

from __future__ import annotations

import argparse
import os
import sys
import textwrap
from pathlib import Path
from typing import List, Optional

from .apparatus import LedgerError, World, find_world, materialize

WIDTH = 78


def wrap(text: str, indent: str = "    ") -> str:
    return textwrap.fill(text, width=WIDTH, initial_indent=indent, subsequent_indent=indent)


def label(entry: dict) -> str:
    """One line describing an entry, used in listings."""
    body = entry["body"]
    kind = entry["kind"]
    if kind == "probe":
        text = body["question"]
    elif kind == "chisel":
        text = body["constraint"]
    elif kind == "beam":
        text = "%s  [%s]" % (body["name"], body["check"])
    elif kind == "boundary":
        text = body["refusal"]
    elif kind == "rehearsal":
        text = "%s  (exit %s, %d file(s) would change)" % (
            body["intent"],
            body["exit"],
            body.get("changed_count", len(body.get("changed", []))),
        )
    elif kind == "receipt":
        text = body["text"]
        if "resolves" in body:
            text += "  (resolves #%d)" % body["resolves"]
        if "retires" in body:
            text += "  (retires #%d)" % body["retires"]
    elif kind == "cognition":
        text = "%s by %s" % (body["phase"], entry["actor"])
        if body.get("summary"):
            text += ": " + body["summary"]
        if body.get("unslept"):
            text += "  (previous cognition #%d never slept)" % body["unslept"]
    else:
        text = repr(body)
    return "#%-3d %-9s %s" % (entry["seq"], kind, text)


def render_beams(results: List[dict]) -> str:
    if not results:
        return "    (no beams yet; the world has no invariants to hold it up)"
    lines = []
    for r in results:
        mark = "ok  " if r["ok"] else "FAIL"
        lines.append("    %s  #%d %s" % (mark, r["seq"], r["name"]))
        if not r["ok"] and r["output"].strip():
            for out_line in r["output"].strip().splitlines()[-8:]:
                lines.append("          | " + out_line)
    return "\n".join(lines)


def render_status(world: World, beams: Optional[List[dict]] = None) -> str:
    entries = world.entries()
    problems = world.verify_chain(entries)
    cognition = world.current_cognition(entries)
    out: List[str] = []
    out.append("Tendora world: %s" % world.root)
    out.append(
        "journal: %d entries, chain %s" % (len(entries), "intact" if not problems else "BROKEN")
    )
    for p in problems:
        out.append("    ! " + p)
    if cognition:
        out.append(
            "cognition: #%d awake since %s (%s)"
            % (cognition["seq"], cognition["ts"], cognition["actor"])
        )
    else:
        out.append("cognition: none awake")

    def section(title: str, kind: str) -> None:
        items = world.active(kind, entries)
        out.append("")
        out.append("%s (%d active)" % (title, len(items)))
        for e in items:
            out.append(wrap(label(e), "  "))

    section("boundaries", "boundary")
    section("chisels", "chisel")
    section("beams", "beam")
    if beams is not None:
        out.append(render_beams(beams))
    section("open probes", "probe")

    recent = [e for e in entries if e["kind"] in ("receipt", "rehearsal", "cognition")][-6:]
    out.append("")
    out.append("recent trail")
    for e in recent:
        out.append(wrap(label(e), "  "))
    return "\n".join(out)


def render_entry(entry: dict) -> str:
    lines = [
        "seq:   %d" % entry["seq"],
        "kind:  %s" % entry["kind"],
        "ts:    %s" % entry["ts"],
        "actor: %s" % entry["actor"],
        "prev:  %s" % entry["prev"],
        "hash:  %s" % entry["hash"],
        "body:",
    ]
    for key, value in entry["body"].items():
        if isinstance(value, str) and "\n" in value:
            lines.append("  %s: |" % key)
            lines.extend("    " + l for l in value.splitlines())
        else:
            lines.append("  %s: %s" % (key, value))
    return "\n".join(lines)


# ---------------------------------------------------------------------------


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="tendora",
        description="Acts upon a Tendora world: probe, chisel, beam, boundary, "
        "rehearse, receipt, wake, sleep.",
    )
    parser.add_argument("--world", help="world root (default: search upward from cwd)")
    parser.add_argument(
        "--actor", help="who is acting (default: $TENDORA_ACTOR, then $USER)"
    )
    sub = parser.add_subparsers(dest="cmd")
    sub.required = True

    p = sub.add_parser("init", help="materialize a new world in a directory")
    p.add_argument("path", nargs="?", default=".", help="directory (default: cwd)")

    p = sub.add_parser("probe", help="put a question to the world")
    p.add_argument("question")

    p = sub.add_parser("chisel", help="record a constraint on what may be built")
    p.add_argument("constraint")

    p = sub.add_parser("beam", help="record an invariant with a shell check")
    p.add_argument("name")
    p.add_argument("--check", required=True, help="shell command; exit 0 means the beam holds")

    p = sub.add_parser("boundary", help="record a refusal")
    p.add_argument("refusal")

    p = sub.add_parser("receipt", help="record what was actually done")
    p.add_argument("text")
    p.add_argument("--resolves", type=int, metavar="SEQ", help="probe this receipt answers")
    p.add_argument(
        "--retires", type=int, metavar="SEQ", help="chisel, beam or boundary this receipt retires"
    )

    p = sub.add_parser("rehearse", help="run a command in a disposable copy of the world")
    p.add_argument("intent", help="what you are trying to find out")
    p.add_argument("-c", "--command", required=True)
    p.add_argument("--timeout", type=int, default=300)

    sub.add_parser("verify", help="check the chain and run every beam")
    sub.add_parser("status", help="brief the reader on the world")

    p = sub.add_parser("log", help="list journal entries")
    p.add_argument("-n", type=int, default=0, help="only the last N")
    p.add_argument("--kind", choices=["probe", "chisel", "beam", "boundary", "rehearsal", "receipt", "cognition"])
    p.add_argument("--all", action="store_true", help="include resolved and retired entries")

    p = sub.add_parser("show", help="print one entry in full")
    p.add_argument("seq", type=int)

    sub.add_parser("wake", help="open a cognition: verify, run beams, brief")

    p = sub.add_parser("sleep", help="close the cognition with a summary")
    p.add_argument("summary")

    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    actor = args.actor
    try:
        if args.cmd == "init":
            world = materialize(Path(args.path), actor=actor)
            print("materialized world at %s" % world.root)
            print("next: python3 -m tendora wake")
            return 0

        world = World(args.world) if args.world else World(find_world())

        if args.cmd == "probe":
            e = world.probe(args.question, actor)
            print("probe #%d recorded" % e["seq"])
        elif args.cmd == "chisel":
            e = world.chisel(args.constraint, actor)
            print("chisel #%d recorded" % e["seq"])
        elif args.cmd == "beam":
            e = world.beam(args.name, args.check, actor)
            print("beam #%d recorded; run `python3 -m tendora verify` to test it" % e["seq"])
        elif args.cmd == "boundary":
            e = world.boundary(args.refusal, actor)
            print("boundary #%d recorded" % e["seq"])
        elif args.cmd == "receipt":
            e = world.receipt(args.text, args.resolves, args.retires, actor)
            print("receipt #%d recorded" % e["seq"])
        elif args.cmd == "rehearse":
            e = world.rehearse(args.intent, args.command, args.timeout, actor)
            body = e["body"]
            print("rehearsal #%d recorded: exit %s" % (e["seq"], body["exit"]))
            if body["changed"]:
                print("  would change %d file(s):" % body["changed_count"])
                for path in body["changed"][:20]:
                    print("    " + path)
                if body["changed_count"] > 20:
                    print("    ... and %d more" % (body["changed_count"] - 20))
            else:
                print("  would change nothing")
            if body["output"].strip():
                print("  output (tail):")
                for line in body["output"].strip().splitlines()[-12:]:
                    print("    | " + line)
            print("  the world itself was not touched")
        elif args.cmd == "verify":
            problems = world.verify_chain()
            if problems:
                print("chain BROKEN:")
                for p in problems:
                    print("  ! " + p)
            else:
                print("chain intact (%d entries)" % len(world.entries()))
            results = world.run_beams()
            print("beams:")
            print(render_beams(results))
            failed = [r for r in results if not r["ok"]]
            return 1 if (problems or failed) else 0
        elif args.cmd == "status":
            print(render_status(world))
        elif args.cmd == "log":
            entries = world.entries()
            if not args.all:
                closed = world.closed(entries)
                entries = [e for e in entries if e["seq"] not in closed]
            if args.kind:
                entries = [e for e in entries if e["kind"] == args.kind]
            if args.n:
                entries = entries[-args.n :]
            for e in entries:
                print(wrap(label(e), ""))
        elif args.cmd == "show":
            print(render_entry(world.get(args.seq)))
        elif args.cmd == "wake":
            entry, beams, unslept = world.wake(actor)
            print("cognition #%d awake (%s)" % (entry["seq"], entry["actor"]))
            if unslept is not None:
                print(
                    "note: cognition #%d (%s, %s) never slept; its last intentions are in the trail"
                    % (unslept["seq"], unslept["actor"], unslept["ts"])
                )
            print()
            print(render_status(world, beams))
            failed = [r for r in beams if not r["ok"]]
            print()
            if failed:
                print("%d beam(s) do not hold. Repair them before building on top." % len(failed))
            else:
                print("All beams hold. Read CONTINUING.md, then choose a probe or make one.")
            print("Before leaving: python3 -m tendora sleep \"what you did\"  then commit.")
            return 1 if failed else 0
        elif args.cmd == "sleep":
            entry, beams = world.sleep(args.summary, actor)
            print("cognition closed by #%d" % entry["seq"])
            print(render_beams(beams))
            git = entry["body"]["git"]
            if git == "none":
                print("this world is not a git repository; the journal is its only witness.")
                print("if you are allowed to, make one:")
                print("    git init -b main && git add -A && git commit -m \"Sleep: %s\"" % args.summary[:60])
            else:
                if git == "dirty":
                    print("git tree was dirty before this sleep entry; commit everything now:")
                else:
                    print("the sleep entry itself changed the journal; commit it:")
                print("    git add -A && git commit -m \"Sleep: %s\"" % args.summary[:60])
            failed = [r for r in beams if not r["ok"]]
            return 1 if failed else 0
        return 0
    except LedgerError as exc:
        print("tendora: %s" % exc, file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
